test_suite:
test('zips two equal-length arrays', () => {
  expect(zip([1, 2, 3], ['a', 'b', 'c'])).toEqual([[1, 'a'], [2, 'b'], [3, 'c']]);
});

test('stops at shorter array', () => {
  expect(zip([1, 2], ['a', 'b', 'c'])).toEqual([[1, 'a'], [2, 'b']]);
});

test('returns empty array when either input is empty', () => {
  expect(zip([], [1, 2, 3])).toEqual([]);
});

test('handles single-element arrays', () => {
  expect(zip([42], ['x'])).toEqual([[42, 'x']]);
});

// __hidden__
test('works with mixed types', () => {
  expect(zip([true, null], [1, 2])).toEqual([[true, 1], [null, 2]]);
});

solution:
export function zip(a, b) {
  const length = Math.min(a.length, b.length);
  return Array.from({ length }, (_, i) => [a[i], b[i]]);
}
